mapper.select:
select * from t_order

    user_id = #{userId}
    and status = #{status}

order by id desc

select o.* from t_order o
where exists (
    select 1 from order_item oi
    join product p on oi.product_id = p.id
    where oi.order_id = o.id and p.create_user_id = #{userId}
)
and o.status = #{status}
order by o.id desc
